using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json.Serialization;

namespace McpServer;

// The [McpServerToolType] attribute registers this class as a container for MCP tools.
// The SDK scans for these at startup and wires them into the tool registry.
[McpServerToolType]
public sealed class WeatherTools
{
    // Each [McpServerTool] method becomes a callable tool exposed to the LLM.
    // The [Description] on the method is what the LLM sees when deciding which tool to use.
    // Parameter [Description]s tell the LLM what values to provide.
    //
    // HttpClient is constructor-injected by the DI container — the SDK resolves
    // tool class instances per-invocation from IServiceProvider.
    [McpServerTool, Description("Get current weather for a city")]
    public static async Task<string> GetWeather(
        HttpClient httpClient,
        [Description("City name, e.g. 'London' or 'New York'")] string city,
        CancellationToken cancellationToken)
    {
        var url = $"https://wttr.in/{Uri.EscapeDataString(city)}?format=j1";
        var data = await httpClient.GetFromJsonAsync<WeatherResponse>(url, cancellationToken);

        if (data?.CurrentCondition is not [var current, ..])
            return $"No weather data found for '{city}'.";

        return $"""
            Weather for {city}:
              Temperature: {current.TempC}°C ({current.TempF}°F)
              Condition:   {current.Description}
              Humidity:    {current.Humidity}%
              Wind:        {current.WindspeedKmph} km/h {current.WindDir}
            """;
    }

    [McpServerTool, Description("Get a short weather forecast for a city (today + next 2 days)")]
    public static async Task<string> GetForecast(
        HttpClient httpClient,
        [Description("City name")] string city,
        CancellationToken cancellationToken)
    {
        var url = $"https://wttr.in/{Uri.EscapeDataString(city)}?format=j1";
        var data = await httpClient.GetFromJsonAsync<WeatherResponse>(url, cancellationToken);

        if (data?.Weather is not { Count: > 0 })
            return $"No forecast data found for '{city}'.";

        var lines = data.Weather.Select(d =>
            $"  {d.Date}: {d.MinTempC}-{d.MaxTempC}°C, {d.Hourly.FirstOrDefault()?.Description ?? "N/A"}");

        return $"Forecast for {city}:\n{string.Join('\n', lines)}";
    }
}

